const lines = [
  'Good morning. One more fold. Meet Phonon. A small voice model, speaking right here in your browser.',
  'A familiar shape. A new voice. This is Phonon, running locally on your device.',
  'Open it up. Hear something new. Every word you hear is generated by Phonon, right here in this browser.',
];

export function createSpeech({ onStatus, onStart, onEnd }) {
  let model;
  let current = null;
  let nextLine = 0;

  function stop() {
    const session = current;
    current = null;
    if (!session) return;
    session.controller.abort();
    void session.context?.close().catch(() => {});
    onStatus('');
  }

  async function play() {
    stop();
    const session = {
      controller: new AbortController(),
      context: null,
      loading: true,
    };
    current = session;
    try {
      session.context = new AudioContext({ sampleRate: 24000 });
      // Resume during the click so playback stays unlocked after the download.
      await session.context.resume();
      if (current !== session) return;
      onStatus('Loading Phonon… First use downloads the voice model.');
      model ??= import('/vendor/phonon-tts/index.js').then(({ PhononTTS }) => PhononTTS.load({
        lang: 'en',
        device: 'cpu',
        onProgress({ loaded, total, cached }) {
          if (!current?.loading || cached) return;
          onStatus(total
            ? `Loading Phonon… ${Math.round(loaded / total * 100)}%`
            : 'Loading Phonon…');
        },
      })).then(async tts => {
        try {
          await tts.addVoice('keynote', '/assets/keynote-voice.safetensors');
          return tts;
        } catch (error) {
          tts.dispose();
          throw error;
        }
      }).catch(error => { model = null; throw error; });
      const tts = await model;
      if (current !== session) return;
      session.loading = false;
      onStatus('Preparing speech…');
      const speech = tts.stream(lines[nextLine++ % lines.length], {
        voice: 'keynote',
        signal: session.controller.signal,
      });
      let end = session.context.currentTime;
      let started = false;
      let lastSource;
      for await (const pcm of speech) {
        if (current !== session) break;
        const buffer = session.context.createBuffer(1, pcm.length, tts.sampleRate);
        buffer.getChannelData(0).set(pcm);
        const source = session.context.createBufferSource();
        source.buffer = buffer;
        source.connect(session.context.destination);
        // Keep a small buffer ahead of the speaker as chunks arrive.
        end = Math.max(end, session.context.currentTime + 0.08);
        source.start(end);
        end += buffer.duration;
        lastSource = source;
        if (!started) {
          started = true;
          onStatus('Speaking locally with Phonon');
          onStart();
        }
      }
      await speech.done;
      if (current !== session) return;
      if (lastSource && end > session.context.currentTime) {
        await new Promise(resolve => {
          lastSource.onended = resolve;
          session.controller.signal.addEventListener('abort', resolve, { once: true });
        });
      }
      if (current !== session) return;
      stop();
      onEnd();
    } catch (error) {
      if (current !== session) return;
      console.error('Phonon playback failed:', error);
      stop();
      onEnd();
      onStatus('Speech could not start. Press Play to retry.');
    }
  }

  return { play, stop, get active() { return current !== null; } };
}
